const parts = msg.topic.split('/');
const requestId = parts[parts.length - 1];

msg.rpcRequestId = requestId;
msg.rpcResponseTopic = 'v1/devices/me/rpc/response/' + requestId;

const rpc = msg.payload || {};

msg.rpcMethod = rpc.method;
msg.rpcParams = rpc.params || {};

// Route to main flow with operation type
if (msg.rpcMethod === 'getBatteryCapacityConfig') {
    msg.isRpcRequest = true;
    msg.operationType = 'read';
    return msg;
}
else if (msg.rpcMethod === 'setBatteryCapacityConfig') {
    msg.isRpcRequest = true;
    msg.operationType = 'write';
    return msg;
}
else {
    return null;
}
